import ctypes
import json
import logging
import os
import subprocess
import time
import numpy as np
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - [%(filename)s:%(lineno)d] - %(message)s',
)

class V25NativeBridge:
    def __init__(self, lib_path: Path):
        if not lib_path.exists():
            raise FileNotFoundError(f"JAIDE V25 native library not found at {lib_path}")
        self.lib = ctypes.CDLL(str(lib_path))
        self._define_api()
        logging.info("Initializing native JAIDE V25 system...")
        self.system_handle = self.lib.jaide_v25_system_create()
        if not self.system_handle:
            raise RuntimeError("Failed to create JAIDE V25 system handle. Check Zig runtime logs.")
        logging.info(f"Native system handle created: {self.system_handle}")

    def _define_api(self):
        self.lib.jaide_v25_system_create.restype = ctypes.c_void_p
        self.lib.jaide_v25_system_destroy.argtypes = [ctypes.c_void_p]
        self.lib.jaide_v25_system_destroy.restype = None
        self.lib.jaide_v25_run_inference.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.POINTER(ctypes.c_char_p)]
        self.lib.jaide_v25_run_inference.restype = ctypes.c_int
        self.lib.jaide_v25_run_distributed_training.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.lib.jaide_v25_run_distributed_training.restype = ctypes.c_bool
        self.lib.jaide_v25_free_string.argtypes = [ctypes.c_char_p]
        self.lib.jaide_v25_free_string.restype = None

    def run_inference(self, prompt: str) -> str:
        prompt_bytes = prompt.encode('utf-8')
        response_ptr = ctypes.c_char_p()
        result_code = self.lib.jaide_v25_run_inference(
            self.system_handle, prompt_bytes, ctypes.byref(response_ptr)
        )
        if result_code != 0:
            raise RuntimeError(f"Native inference failed with error code {result_code}")
        if not response_ptr.value:
            logging.error("Native inference returned a null pointer for the response.")
            return ""
        response_str = response_ptr.value.decode('utf-8')
        self.lib.jaide_v25_free_string(response_ptr)
        return response_str

    def run_distributed_training(self, dataset_path: str) -> bool:
        path_bytes = dataset_path.encode('utf-8')
        success = self.lib.jaide_v25_run_distributed_training(self.system_handle, path_bytes)
        return bool(success)

    def destroy(self):
        if self.system_handle:
            logging.info(f"Destroying native system handle: {self.system_handle}")
            self.lib.jaide_v25_system_destroy(self.system_handle)
            self.system_handle = None

class HeuristicGradientMomentum:
    def __init__(
        self,
        params: List[Dict[str, Any]],
        lr: float = 1e-3,
        betas: Tuple[float, float] = (0.9, 0.99),
        eps: float = 1e-8,
        heuristic_momentum_window: int = 10,
        state_matrix_spectral_radius_target: float = 0.99,
        state_matrix_regularization_strength: float = 0.01
    ):
        if not 0.0 <= lr:
            raise ValueError(f"Invalid learning rate: {lr}")
        if not 0.0 <= eps:
            raise ValueError(f"Invalid epsilon value: {eps}")
        if not (0.0 <= betas[0] < 1.0 and 0.0 <= betas[1] < 1.0):
            raise ValueError(f"Invalid beta parameters: {betas}")

        self.defaults = dict(
            lr=lr, betas=betas, eps=eps,
            heuristic_momentum_window=heuristic_momentum_window,
            state_matrix_spectral_radius_target=state_matrix_spectral_radius_target,
            state_matrix_regularization_strength=state_matrix_regularization_strength
        )
        self.param_groups = params
        self.state = {}
        for group in self.param_groups:
            for p in group['params']:
                self.state[id(p)] = {}

    def zero_grad(self):
        for group in self.param_groups:
            for p in group['params']:
                if hasattr(p, 'grad') and p.grad is not None:
                    p.grad = np.zeros_like(p.data)

    def step(self):
        for group in self.param_groups:
            for p in group['params']:
                if not hasattr(p, 'grad') or p.grad is None:
                    continue

                grad = p.grad
                if np.any(np.isinf(grad)) or np.any(np.isnan(grad)):
                    logging.warning("NaN or Inf gradient detected. Skipping update for this parameter.")
                    continue

                state = self.state[id(p)]

                if 'step' not in state:
                    state['step'] = 0
                    state['exp_avg'] = np.zeros_like(p.data)
                    state['exp_avg_sq'] = np.zeros_like(p.data)
                    k = group.get('heuristic_momentum_window', self.defaults['heuristic_momentum_window'])
                    state['grad_history'] = np.zeros((k, *p.data.shape))

                exp_avg, exp_avg_sq = state['exp_avg'], state['exp_avg_sq']
                state['step'] += 1

                if group.get('weight_decay', 0.0) > 0.0:
                    p.data *= (1.0 - group['lr'] * group['weight_decay'])

                k = group.get('heuristic_momentum_window', self.defaults['heuristic_momentum_window'])
                history = state['grad_history']
                history[state['step'] % k] = grad
                beta1, beta2 = group.get('betas', self.defaults['betas'])

                dynamic_beta1 = beta1
                if state['step'] > k:
                    avg_past_grad = np.mean(history, axis=0)
                    norm_grad = np.linalg.norm(grad)
                    norm_avg_past = np.linalg.norm(avg_past_grad)
                    if norm_grad > self.defaults['eps'] and norm_avg_past > self.defaults['eps']:
                        cos_sim = np.dot(grad.flatten(), avg_past_grad.flatten()) / (norm_grad * norm_avg_past)
                        dynamic_beta1 = beta1 * (1.0 + 0.5 * max(0, cos_sim))
                        dynamic_beta1 = min(dynamic_beta1, 0.999)

                exp_avg = dynamic_beta1 * exp_avg + (1 - dynamic_beta1) * grad
                exp_avg_sq = beta2 * exp_avg_sq + (1 - beta2) * (grad**2)
                state['exp_avg'], state['exp_avg_sq'] = exp_avg, exp_avg_sq

                bias_correction1 = 1 - dynamic_beta1 ** state['step']
                bias_correction2 = 1 - beta2 ** state['step']
                step_size = group['lr'] / bias_correction1
                denominator = (np.sqrt(exp_avg_sq) / np.sqrt(bias_correction2)) + group.get('eps', self.defaults['eps'])
                update = step_size * (exp_avg / denominator)

                if group.get('is_state_matrix', False):
                    row_sums = np.sum(np.abs(p.data), axis=1)
                    target = group.get('state_matrix_spectral_radius_target', self.defaults['state_matrix_spectral_radius_target'])
                    overshoot = np.maximum(0, row_sums - target)
                    reg_grad = np.sign(p.data) * overshoot[:, np.newaxis]
                    reg_strength = group.get('state_matrix_regularization_strength', self.defaults['state_matrix_regularization_strength'])
                    update += group['lr'] * reg_strength * reg_grad

                p.data -= update

class JAIDEV25Orchestrator:
    def __init__(self):
        logging.info("Initializing JAIDE V25 Python Orchestrator...")
        self.root_path = Path(__file__).parent.resolve()
        self.build_dir = self.root_path / "build"

        lib_name = "libjaide_v25.so"
        if os.name == 'nt':
            lib_name = "jaide_v25.dll"
        elif hasattr(os, 'uname') and os.uname().sysname == 'Darwin':
            lib_name = "libjaide_v25.dylib"
        self.lib_path = self.build_dir / lib_name
        self.bridge: Optional[V25NativeBridge] = None

    def build_system(self):
        logging.info("Building JAIDE V25 native runtime...")
        build_script = self.root_path / "scripts" / "build_jaideV25.sh"
        if not build_script.exists():
            raise FileNotFoundError(f"Build script not found at {build_script}")

        self.build_dir.mkdir(exist_ok=True)
        try:
            process = subprocess.run(
                ["bash", str(build_script)],
                capture_output=True, text=True, check=True, cwd=self.root_path
            )
            logging.info("Build script stdout:\n" + process.stdout)
            if process.stderr:
                logging.warning("Build script stderr:\n" + process.stderr)
        except subprocess.CalledProcessError as e:
            logging.error("Build failed. Native library could not be created.")
            logging.error(f"Return code: {e.returncode}\nStdout: {e.stdout}\nStderr: {e.stderr}")
            raise RuntimeError("Build failed.") from e

        if not self.lib_path.exists():
            raise RuntimeError(f"Build succeeded but native library not found at: {self.lib_path}")
        logging.info("Native runtime built successfully.")

    def start(self):
        if not self.lib_path.exists():
            self.build_system()
        logging.info("Starting JAIDE V25 system via native bridge...")
        self.bridge = V25NativeBridge(self.lib_path)
        logging.info("JAIDE V25 system is online and ready.")

    def stop(self):
        if self.bridge:
            logging.info("Shutting down JAIDE V25 system...")
            self.bridge.destroy()
            self.bridge = None
            logging.info("System offline.")

    def run_inference_demo(self):
        if not self.bridge:
            raise RuntimeError("System is not running. Call start() first.")

        prompt = "Demonstrate the operation of the Heuristic Gradient Momentum optimizer and compare it to the Adam optimizer."
        logging.info(f"Running inference demo with prompt: '{prompt}'")
        try:
            start_time = time.time()
            response = self.bridge.run_inference(prompt)
            duration = time.time() - start_time
            logging.info(f"Inference response received in {duration:.2f}s:\n---\n{response}\n---")
        except Exception as e:
            logging.error(f"Inference demo failed: {e}", exc_info=True)

    def run_training_demo(self):
        if not self.bridge:
            raise RuntimeError("System is not running. Call start() first.")

        dataset_path = self.root_path / "data" / "genesis_sample.txt"
        dataset_path.parent.mkdir(exist_ok=True)
        if not dataset_path.exists():
            logging.warning(f"Demo dataset not found at {dataset_path}. Creating a dummy file.")
            with open(dataset_path, "w", encoding="utf-8") as f:
                f.write("This is a sample text in English for demonstrating the distributed training of JAIDE V25. The system must process this text and update the model weights in a distributed manner.")

        logging.info(f"Starting distributed training demo with dataset: {dataset_path}")
        try:
            start_time = time.time()
            success = self.bridge.run_distributed_training(str(dataset_path))
            duration = time.time() - start_time
            if success:
                logging.info(f"✅ Distributed training demo completed successfully in {duration:.2f}s.")
            else:
                logging.error(f"❌ Distributed training demo failed after {duration:.2f}s.")
        except Exception as e:
            logging.error(f"Training demo failed with an exception: {e}", exc_info=True)

    def run_optimizer_demo(self):
        logging.info("Running custom HGM optimizer demo...")

        class MockParam:
            def __init__(self, data):
                self.data = data.astype(np.float32)
                self.grad = np.random.randn(*data.shape).astype(np.float32) * 0.1

        params = [
            {'params': [MockParam(np.random.randn(128, 256)) for _ in range(5)]},
            {
                'params': [MockParam(np.random.randn(256, 256) * 0.5)],
                'is_state_matrix': True, 'lr': 0.001, 'weight_decay': 0.0
            }
        ]

        optimizer = HeuristicGradientMomentum(params, lr=0.002)
        initial_norm = np.linalg.norm(params[0]['params'][0].data)
        logging.info(f"Initial parameter norm (first layer): {initial_norm:.6f}")

        optimizer.step()

        final_norm = np.linalg.norm(params[0]['params'][0].data)
        logging.info(f"Parameter norm after one step: {final_norm:.6f}")

        if np.isclose(initial_norm, final_norm):
            logging.warning("Optimizer step resulted in a negligible parameter change.")
        else:
            logging.info("✅ HGM optimizer step executed successfully.")

if __name__ == "__main__":
    orchestrator = JAIDEV25Orchestrator()
    try:
        orchestrator.start()
        print("\n" + "="*80)
        orchestrator.run_inference_demo()
        print("\n" + "="*80)
        orchestrator.run_training_demo()
        print("\n" + "="*80)
        orchestrator.run_optimizer_demo()
        print("\n" + "="*80)
    except Exception as e:
        logging.critical(f"A critical error occurred in the orchestrator: {e}", exc_info=True)
    finally:
        orchestrator.stop()
