// Tokenization utilities
proc tokenizeText(text: string): [] int {
  // Simplified tokenization - in practice would use SentencePiece or similar
  var tokens: [0..#text.size] int;

  for (i, char) in zip(0..#text.size, text) do
    tokens[i] = char:int % vocabSize;

  return tokens;
}

// Inference utilities
proc generateText(model: shared JadeModel, prompt: [] int, maxLength: int): [] int {
  var generated: [0..#maxLength] int;

  // Copy prompt
  forall i in 0..#prompt.size do
    generated[i] = prompt[i];

  var currentLength = prompt.size;

  while currentLength < maxLength {
    // Get logits for current sequence
    var logits: [currentLength * vocabSize] ModelParam;
    model!.forward(generated[0..currentLength], logits);

    // Sample next token (greedy for simplicity)
    const lastTokenLogits = logits[(currentLength - 1) * vocabSize..currentLength * vocabSize - 1];
    const nextToken = maxloc reduce zip(lastTokenLogits, 0..#vocabSize);

    generated[currentLength] = nextToken[1];
    currentLength += 1;
  }

  return generated;
}

// Performance benchmarking
proc benchmarkModel(model: shared JadeModel, numRuns: int) {
  writeln("Benchmarking model performance...");

  var rng = new randomStream(eltType=int, seed=999);
  var dummyInput: [0..#seqLen] int;

  forall i in 0..#seqLen do
    dummyInput[i] = rng.next(0, vocabSize - 1);

  var timer: stopwatch;
  timer.start();

  for run in 0..#numRuns {
    var logits: [seqLen * vocabSize] ModelParam;
    model!.forward(dummyInput, logits);
  }

  timer.stop();

  const avgTime = timer.elapsed() / numRuns;
  const tokensPerSecond = seqLen / avgTime;

  writeln("Average inference time: ", avgTime, " seconds");
  writeln("Tokens per second: ", tokensPerSecond);
  writeln("FLOPS estimate: ", (numLayers * dModel * dState * seqLen * 2) / avgTime / 1e9, " GFLOPS");
}

// Main training procedure
proc main() {
  writeln("JAIDE V25 Chapel Distributed Training System");
  writeln("Nodes: ", numNodes, ", Total GPUs: ", numNodes * numGPUsPerNode);

  // Initialize distributed training
  const trainer = new DistributedTrainer();

  // Load or generate training data
  const trainingData = loadTrainingData("training_corpus.txt");

  // Start training
  trainer.train(trainingData);

  // Run benchmarks
  benchmarkModel(trainer.model, 100);

  // Demo text generation
  const prompt = tokenizeText("The future of AI is");
  const generated = generateText(trainer.model, prompt, 50);

  writeln("Generated text tokens: ", generated);

  writeln("Training complete!");
}
