proc enqueue*(queue: TaskQueue, task: Task): bool =
  withLock queue.lock:
    if queue.tasks.len >= queue.maxSize:
      return false
    queue.tasks.add(task)
    queue.currentSize.fetchAdd(1)
    signal(queue.condition)
    return true

proc dequeue*(queue: TaskQueue): Option[Task] =
  withLock queue.lock:
    if queue.tasks.len == 0:
      return none(Task)

    # Priority-based dequeue
    var highestIdx = 0
    var highestPriority = queue.tasks[0].priority

    for i in 1..<queue.tasks.len:
      if queue.tasks[i].priority > highestPriority:
        highestPriority = queue.tasks[i].priority
        highestIdx = i

    result = some(queue.tasks[highestIdx])
    queue.tasks.delete(highestIdx)
    queue.currentSize.fetchSub(1)

proc steal*(queue: TaskQueue, maxTasks: int = 1): seq[Task] =
  withLock queue.lock:
    if queue.tasks.len <= 1:
