    let stealCount = min(maxTasks, queue.tasks.len div 2)
    result = queue.tasks[queue.tasks.len - stealCount..^1]
    queue.tasks.setLen(queue.tasks.len - stealCount)
    queue.currentSize.fetchSub(stealCount)

